// Output follows the Notify subflow contract: to, title, message, icon, channel,
// persistent, sticky, extraData (tag, color, group, progress, chronometer, ...).
const MODES = {
    grill: 'Grillen', smoker: 'Smoker', bake: 'Backen', roast: 'Braten',
    broil: 'Überbacken', dehydrate: 'Dörren', reheat: 'Aufwärmen',
    'air crisp': 'Heißluft', griddle: 'Grillplatte',
};
const PROMPT_ICON = { addfood: 'mdi:food-steak', flipfood: 'mdi:flip-horizontal', getfood: 'mdi:silverware-fork-knife', closelid: 'mdi:square-rounded', done: 'mdi:check-circle' };
// Tags and the group are namespaced per grill (ev.dsn): two grills
// cooking at once must not replace or clear each other's notifications.
const slug = () => String(ev.dsn || 'grill').replace(/[^A-Za-z0-9]/g, '_');
const TAG = () => `woodfire_${slug()}_progress`;
const promptTag = () => `woodfire_${slug()}_prompt`;
const probeTag = (i) => `woodfire_${slug()}_probe${i}`;

const ev = msg.payload.event || {};
const type = msg.payload.event_type || msg.topic;
const now = Math.floor(Date.now() / 1000);
const mins = (s) => Math.max(0, Math.round((s || 0) / 60));
const probeName = (i) => `Probe ${(i || 0) + 1}`;

// Grill mode reports the firmware's internal °C target; show the heat level instead.
function target() {
    const sp = ev.setpoint;
    if (sp === undefined || sp === null) return '';
    if (ev.mode !== 'grill') return ` bei ${sp}°C`;
    const level = sp <= 3 ? sp : sp < 175 ? 1 : sp < 215 ? 2 : 3;
    return ` · ${['Niedrig', 'Mittel', 'Hoch'][level - 1]}`;
}
const label = () => (MODES[ev.mode] || ev.mode || 'Garen') + target();

function note(title, message, opts) {
    // Generic HA notify payload. The `data` keys follow the companion-app
    // (mobile_app) notification conventions: tag, color, group, channel,
    // sticky, chronometer, when, alert_once, progress, progress_max.
    const { icon = 'mdi:grill', persistent = false, sticky = false, ...extra } = opts;
    return {
        title, message,
        data: { group: `woodfire_cook_${slug()}`, channel: 'woodfire', sticky, persistent,
                notification_icon: icon, ...extra },
    };
}
// clear_notification is a mobile_app feature: it dismisses a tagged notification.
const clear = (tag) => ({ message: 'clear_notification', data: { tag } });

function build() {
    switch (type) {
        case 'ninja_woodfire_cook_started':
            return [note('🔥 Grill gestartet',
                `${label()} · ${mins(ev.seconds_set)} Min${ev.smoke ? ' · 🌲 Rauch' : ''}\nVorheizen läuft…`,
                { icon: 'mdi:fire-alert', color: '#ff6b35', tag: TAG(), persistent: true, sticky: true, alert_once: true,
                  progress_indeterminate: true, chronometer: true, when: now })];
        case 'ninja_woodfire_preheat_complete':
            // The cook timer starts once preheat ends: count down to the end.
            return [note('✅ Vorheizen abgeschlossen', `${label()}\nJetzt Grillgut auflegen!`,
                { icon: 'mdi:food-steak', color: '#4caf50', tag: TAG(), persistent: true, sticky: true, alert_once: false,
                  ...(ev.seconds_set ? { chronometer: true, when: now + ev.seconds_set } : {}) })];
        case 'ninja_woodfire_cook_halftime':
            return [note('⏱️ Halbzeit', `Noch ${mins(ev.seconds_left)} Min · Zeit zum Wenden?`,
                { icon: 'mdi:timer-sand', color: '#ff9800', tag: TAG(), persistent: true, sticky: true, alert_once: false,
                  progress: (ev.seconds_set || 0) - (ev.seconds_left || 0), progress_max: ev.seconds_set || 1,
                  chronometer: true, when: now + (ev.seconds_left || 0) })];
        case 'ninja_woodfire_probe_halfway': {
            const current = Math.round(ev.current || 0);
            return [note(`🌡️ ${probeName(ev.probe_index)} auf halbem Weg`,
                `${current}°C von ${ev.target}°C · noch ${Math.max(0, ev.target - current)}°C`,
                { icon: 'mdi:thermometer', color: '#2196f3', tag: probeTag(ev.probe_index),
                  persistent: true, sticky: true, alert_once: false,
                  progress: current, progress_max: ev.target || 1 })];
        }
        case 'ninja_woodfire_probe_target_reached':
            return [note(`✅ ${probeName(ev.probe_index)} fertig`,
                `Zieltemperatur ${ev.target}°C erreicht 🎯 (aktuell ${Math.round(ev.current || 0)}°C)`,
                { icon: 'mdi:check-circle', color: '#4caf50', tag: probeTag(ev.probe_index) })];
        case 'ninja_woodfire_cook_done': {
            const done = ev.reason !== 'stopped';
            // Replace the progress notification and clear leftover probe progress.
            return [
                note(done ? '🎉 Grill fertig' : '⏹️ Grill gestoppt',
                    done ? 'Fertig gegrillt! Guten Appetit 🍖' : 'Der Garvorgang wurde beendet.',
                    { icon: done ? 'mdi:check-circle' : 'mdi:stop-circle', color: done ? '#4caf50' : '#ff9800', tag: TAG() }),
                clear(probeTag(0)),
                clear(probeTag(1)),
                clear(promptTag()),
            ];
        }
        case 'ninja_woodfire_prompt': {
            const PROMPTS = {
                addfood: ['\ud83c\udf57 Grillgut auflegen', 'Vorheizen fertig \u2014 jetzt auflegen!'],
                flipfood: ['\ud83d\udd04 Wenden', 'Zeit zum Wenden des Grillguts.'],
                getfood: ['\ud83c\udf7d\ufe0f Entnehmen', 'Grillgut entnehmen.'],
                closelid: ['\ud83d\udd3d Deckel schlie\u00dfen', 'Bitte den Deckel schlie\u00dfen.'],
                done: ['\u2705 Fertig', 'Garvorgang abgeschlossen.'],
            };
            const pr = PROMPTS[ev.prompt] || [`Hinweis: ${ev.prompt}`, ''];
            return [note(pr[0], pr[1], { icon: PROMPT_ICON[ev.prompt] || 'mdi:bell-ring', color: '#ff9800',
                tag: promptTag(), persistent: true, sticky: true })];
        }
        default:
            return [];
    }
}

const msgs = build();
// Emit one message per notification on the single output.
return msgs.length ? [msgs.map((m) => ({ ...msg, payload: m }))] : null;
